/* Emits icons-runtime.js — the handful of icons that JS injects at runtime
   (play/pause, arrows, the donate-note icons). Generated, not hand-written,
   so they can never drift from the markup icons. */
const fs = require('fs');
const { icon } = require('./icons.js');

const RUNTIME = {
  play: icon('play'),
  pause: icon('pause'),
  arrowRight: icon('arrow-right', 'mog-icon--trail'),
  arrowDown: icon('arrow-down', 'mog-icon--trail'),
  arrowUp: icon('arrow-up', 'mog-icon--trail'),
  heart: icon('heart'),
  sprout: icon('sprout'),
};

const out =
  '/* AUTO-GENERATED by .build/gen-runtime-icons.js — do not edit by hand. */\n' +
  '/* Icons that JavaScript injects at runtime. Must load before script.js. */\n' +
  'window.MOG_ICON = ' + JSON.stringify(RUNTIME, null, 2) + ';\n';

fs.writeFileSync('icons-runtime.js', out);
console.log('icons-runtime.js written (' + Object.keys(RUNTIME).length + ' icons)');
